  if(slinks[0]) slinks[0].lastChild.textContent=L('nav.about');
  if(slinks[1]) slinks[1].lastChild.textContent=L('nav.download');
  var lbtn=$('g-login-btn'); if(lbtn) lbtn.textContent=L('side.login');
  /* 접힌 레일, 하단 아이콘의 호버 픽 */
  var po=$('gp-open'); if(po) po.textContent=L('side.open');
  var pc=$('gp-close'); if(pc) pc.textContent=L('side.close');
  var pn=$('gp-new'); if(pn) pn.textContent=L('side.newTip');
  var pst=$('gp-set'); if(pst) pst.textContent=L('menu.settings');
  var pf=$('g-profile'); if(pf && !S.user) pf.textContent=L('nav.login');
  /* 피드백 패널 */
  var F=function(id,k){var el=$(id); if(el) el.textContent=L(k);};
  F('fb-title','fb.title'); F('fb-lbl','fb.label'); F('fb-sens-t','fb.sens');
  F('fb-tip','fb.tip'); F('fb-shot-desc','fb.shot'); F('fb-attach-t','fb.attach');
  F('fb-send','fb.send'); F('fb-done-t','fb.doneT'); F('fb-done-p','fb.doneP'); F('fb-done-x','common.close');
  var ft=$('fb-text'); if(ft) ft.placeholder=L('fb.ph');
  var ff=$('fb-fine'); if(ff) ff.innerHTML=L('fb.fine')
    .replace('{P}','<a href="policies/#privacy" target="_blank" rel="noopener noreferrer">')
    .replace('{T}','<a href="policies/#terms" target="_blank" rel="noopener noreferrer">')
    .replace(/\{\/\}/g,'</a>');
  /* 주요 aria-label */
  var hb2=$('g-hamburger'); if(hb2) hb2.setAttribute('aria-label',L('common.menu'));
  var gb2=$('g-globe'); if(gb2) gb2.setAttribute('aria-label',L('menu.glc'));
  document.querySelectorAll('#glc-panel .x2,.fb-x,#fb-done .cls').forEach(function(el){el.setAttribute('aria-label',L('common.close'));});
  var gr2=$('g-gear-btn'); if(gr2) gr2.setAttribute('aria-label',L('menu.settings'));
  /* 레일 버튼 aria — 로그인 전 표면에 노출되는 것들 */
  var so2=document.querySelector('#g-side-toggle .g-ico-btn'); if(so2) so2.setAttribute('aria-label',L('side.open'));
  var sc9=null; /* 토글 aria 는 위 so2(#g-side-toggle)가 담당 */
  document.querySelectorAll('button[onclick="gHome()"]').forEach(function(b){ b.setAttribute('aria-label',L('side.newTip')); });
  document.querySelectorAll('[onclick="gProfileClick(event)"]').forEach(function(b){ if(!S.user) b.setAttribute('aria-label',L('nav.login')); });
  /* 설정 메뉴 */
  var items=document.querySelectorAll('#g-setmenu>.gm-item, #g-setmenu>button.gm-item');
  document.querySelectorAll('#g-setmenu .gm-item').forEach(function(it){
    var t=it.childNodes; /* 텍스트 노드 교체 */
  });
  var menuMap=[['theme','menu.theme'],['help','menu.help']];
  var themeItem=document.querySelector('[onclick*="gmSub(event,\'theme\')"]');
  var helpItem=document.querySelector('[onclick*="gmSub(event,\'help\')"]');
  function setItemLabel(el,txt){ if(!el) return; for(var i=0;i<el.childNodes.length;i++){ var n=el.childNodes[i]; if(n.nodeType===3 && n.textContent.trim()){ n.textContent=txt; return; } } }
  setItemLabel(themeItem,L('menu.theme'));
  setItemLabel(helpItem,L('menu.help'));
  var fbItem=document.querySelector('#g-setmenu button.gm-item'); setItemLabel(fbItem,L('menu.feedback'));
  var setItem=document.querySelector('[onclick*="gmSub(event,\'set\')"]'); setItemLabel(setItem,L('menu.settings'));
  var setSt=$('gm-set-st'); if(setSt) setSt.textContent=L('menu.settings');
  var glcLbl=$('gm-glc-lbl'); if(glcLbl) glcLbl.textContent=L('menu.glc');
  var it=$('glc-info-txt'); if(it) it.textContent=L('glc.info');
  /* 언어/통화 패널 내부 정적 텍스트 */
  var tl=$('glc-tab-l'); if(tl) tl.textContent=L('glc.lang');
  var tc=$('glc-tab-c'); if(tc) tc.textContent=L('glc.curTab');
  var hl=$('glc-h-lang'); if(hl) hl.textContent=L('glc.lang');
  var hc=$('glc-h-cur'); if(hc) hc.textContent=L('glc.cur');
  var sl=$('glc-srch-l'); if(sl) sl.placeholder=L('glc.search');
  var sc2=$('glc-srch-c'); if(sc2) sc2.placeholder=L('glc.search');
  try{ document.documentElement.lang=GLC.lang; }catch(e){}
  var tsub=document.querySelectorAll('#gm-sub-theme [data-theme]');
  var tkeys=['menu.system','menu.light','menu.dark'];
  tsub.forEach(function(b,i){ for(var j=0;j<b.childNodes.length;j++){ var n=b.childNodes[j]; if(n.nodeType===3){ n.textContent=L(tkeys[i]); return; } } });
  var tst=document.querySelector('#gm-sub-theme .st'); if(tst) tst.textContent=L('menu.themeTitle');
  var hsub=document.querySelectorAll('#gm-sub-help a');
  var hkeys=['menu.terms','menu.privacy','nav.about'];
  hsub.forEach(function(a,i){ a.textContent=L(hkeys[i]); });
  var hst=document.querySelector('#gm-sub-help .st'); if(hst) hst.textContent=L('menu.help');
  /* 배너 */
  var bsub=document.querySelector('#g-appbanner .t span'); if(bsub) bsub.textContent=L('banner.sub');
  var bdl=document.querySelector('#g-appbanner .dl'); if(bdl) bdl.textContent=L('banner.dl');
  /* 고객센터/지구본/언어 툴팁 */
  var tip=document.querySelector('#teth-help .tip'); if(tip) tip.textContent=L('help.tip');
  var gt=$('g-globe-tip'); if(gt) gt.textContent=L('menu.glc');
  var lt=$('glc-lang-tip'); if(lt) lt.textContent=L('glc.info');
  /* 인증 모달 (시작 화면) */
  var at=document.querySelector('#au-start .au-title'); if(at) at.textContent=L('auth.title');
  var as=document.querySelector('#au-start .au-sub'); if(as) as.innerHTML=L('auth.sub');
  document.querySelectorAll('#au-start .au-btn').forEach(function(b){
    var t=b.textContent;
    var last=b.childNodes[b.childNodes.length-1];
    if(/Google/.test(t) && last.nodeType===3) last.textContent=L('auth.google');
    else if(/Apple/.test(t) && last.nodeType===3) last.textContent=L('auth.apple');
    else if(b.classList.contains('primary')) b.textContent=L('auth.continue');
  });
  var adiv=document.querySelector('#au-start .au-div'); if(adiv) adiv.textContent=L('auth.or');
  var aem=$('au-email'); if(aem) aem.placeholder=L('auth.email');
  var af=$('au-free'); if(af) af.textContent=L('auth.free');
  /* 고객센터 팝오버 */
  var hp=document.getElementById('teth-help-pop');
  if(hp){
    var hb=hp.querySelector('b'); if(hb) hb.innerHTML='<i></i>'+L('help.title');
    var hs=hp.querySelector('.sub');
    hp.childNodes.forEach(function(n){ if(n.nodeType===3 && n.textContent.trim()) n.textContent=L('help.body'); });
    if(hs) hs.textContent=L('help.sub');
  }
  /* 홈 리렌더 (헤드라인/부제/칩/약관) — 홈 화면일 때만 */
  if(G && G.mode==='home' && typeof gHome==='function') gHome();
}
